"schulungen": {
  "meta": {
    "title": "Training | K Aqua",
    "desc": "K Aqua Training & Certification: Master PP-R welding techniques and installation best practices through our expert-led German programs."
  },
  "hero": {
    "eyebrow": "GERMAN ENGINEERING ACADEMY",
    "title1": "Examining the",
    "title2": "Industrial Elite.",
    "desc": "The K Aqua training program is no ordinary continuing education. It is the initiation into the uncompromising world of German pipe construction. For engineers and technicians responsible for megaprojects where material failure is not an option, but an absolute catastrophe. We teach in micrometers, we think in decades.",
    "cta1": "Start Academy Application",
    "cta2": "View Curriculum"
  },
  "manifesto": {
    "title1": "Precision",
    "title2": "is <span className=\"text-primary\">no</span>",
    "title3": "accident.",
    "p1": "It is the result of relentless methodology and cold, industrial discipline. When thousands of cubic meters of water are pumped under enormous pressure through the lifelines of a 100-story skyscraper, there is no room for approximations or interpretations.",
    "p2": "The K Aqua training program was developed to close the gap between theoretical knowledge and flawless, mechanical perfection. Those trained in our academy no longer act as mere craftsmen; they become the executing organ of a perfect, deterministic system."
  },
  "bento": {
    "eyebrow": "THE PILLARS OF AUTHORITY",
    "title": "Knowledge as an absolute weapon.",
    "lead": "Our technical training modules are not designed to make it easy for you. They are designed to mercilessly eliminate errors.",
    "items": [
      {
        "title": "Homogeneous Material Fusion",
        "desc": "Beyond bonding or unstable mechanical seals. We train the exact calibration of temperature, pressure, and time to fuse pipes and fittings at the molecular level into an inseparable, monolithic structure."
      },
      {
        "title": "Destructive Analytics",
        "desc": "To understand the limits, you have to exceed them. Practical modules in our high-pressure test rigs with burst pressures well beyond 100 bar. We analyze failure to prevent it in practice."
      },
      {
        "title": "Thermal Linear Expansion",
        "desc": "Ice-cold compensation of temperature fluctuations in large-scale projects through precisely calculated expansion loops and fixed point systems."
      },
      {
        "title": "Aggressive Media & pH Stability",
        "desc": "In-depth analysis of resistance to highly concentrated industrial chemicals. The academy imparts profound knowledge on material fatigue under continuous chemical load and radical pH shifts."
      }
    ]
  },
  "typography": {
    "t1": "ZERO-FAULT",
    "t2": "TOLERANCE."
  },
  "curriculum": {
    "eyebrow": "THE CURRICULUM",
    "title": "Academic Uncompromisingness.",
    "lead": "Four modules. One doctrine. Each segment of our curriculum is geared towards identifying weaknesses in execution and systematically eradicating them."
  },
  "sticky": {
    "items": [
      {
        "title": "Module Alpha: Fluid Mechanics & Kinetics",
        "desc": "The mathematics of water. We break down complex cavitation effects and water hammer scenarios into calculable variables. You learn not only to dampen hydrodynamic shock symptoms but to systematically eliminate them. For pipe networks that operate in complete, silent perfection."
      },
      {
        "title": "Module Beta: Parametric Pipeline Design",
        "desc": "The design of piping systems as an algorithmic discipline. The training includes the use of the latest CAD/BIM tools for collision checking and optimizing material utilization. No guessing. Pure, cold calculation."
      },
      {
        "title": "Module Gamma: Hygiene Architecture & Microbiology",
        "desc": "Legionella prevention at a structural level. How to avoid dead legs, extinguish stagnation zones, and control water temperature stratification in complex ring main systems. The system dictates purity; we leave nothing to chance."
      },
      {
        "title": "Module Delta: The Final K Aqua Audit",
        "desc": "Testing is not a right; it is a privilege. The exam requires the construction and theoretical defense of a self-sufficient water supply system under simulated extreme conditions (e.g., seismic activity, 50°C ambient temperature). Only those who prove absolute flawlessness bear the K Aqua Certificate."
      }
    ]
  },
  "timeline": {
    "title": "The Certification Path.",
    "desc": "The transformation from installer to certified K Aqua Master Engineer follows a strict, relentless rhythm. Only those who walk this path to the end receive authorization for our high-performance systems.",
    "items": [
      {
        "year": "PHASE 01",
        "title": "Material Physics & Onboarding",
        "text": "Grasping the physical limits. A profound introduction to molecular PP-R/PPRCT material specifications. This is where the foundation of industrial toughness is poured."
      },
      {
        "year": "PHASE 02",
        "title": "Laboratory & Stress Tests",
        "text": "Hands-on destruction. Experiencing the burst limit in the test rig and studying microscopic crack formations. Only those who know the weakness can construct absolute strength."
      },
      {
        "year": "PHASE 03",
        "title": "Fusion Doctrine",
        "text": "The perfect welding protocol. Mechanical training of thermodynamic movements up to an infallible, muscular automatism. Every motion is calibrated."
      },
      {
        "year": "PHASE 04",
        "title": "System Architecture",
        "text": "Scaling from a simple pipe segment to the infrastructure of a skyscraper. We execute pressure loss tables, flow velocities, and flow dividers with iron logic."
      },
      {
        "year": "PHASE 05",
        "title": "The Master Exam",
        "text": "A 48-hour audit under the merciless supervision of German Chief Engineers. No tolerance for miscalculations. One mistake means immediate expulsion."
      }
    ]
  },
  "spec": {
    "eyebrow": "GLOBAL STANDARD",
    "title": "The global benchmark for safety.",
    "desc": "Our exam is not just a piece of paper. It is a promise cast in titanium to builders and investors worldwide. Where the K Aqua Certificate is present, the installation has been carried out according to the strictest German engineering standards.",
    "items": [
      {
        "title": "International Validity",
        "text": "Recognized by the world's leading construction and regulatory authorities."
      },
      {
        "title": "Audit Transparency",
        "text": "Seamless, digital documentation of every welding process."
      },
      {
        "title": "Lifelong Authority",
        "text": "Once acquired, it distinguishes the Engineer as part of an elite caste."
      }
    ]
  },
  "cta": {
    "title1": "Ready for",
    "title2": "absolute control?",
    "desc": "Submit to the standard of German engineering. Send us your profile or request the specifications for in-house company audits.",
    "button": "Initiate Application"
  }
},
"zertifizierung": {
  "meta": {
    "title": "Certificates & Standards | K Aqua",
    "desc": "DVGW, SKZ, ISO and more. Discover the uncompromising safety and German Engineering quality of K Aqua piping systems."
  },
  "hero": {
    "eyebrow": "German Engineering Standards",
    "title1": "Certificates.",
    "title2": "Engineered in Germany.",
    "desc": "This module provides uncompromising safety for the most demanding projects worldwide. Manufactured according to the strictest industrial standards to last for generations. Because material failure is never an option.",
    "cta1": "Request Project",
    "cta2": "Technical Manual"
  },
  "manifesto": {
    "title1": "A certificate is just paper.",
    "title2": "The process behind it is made of steel.",
    "p1": "Many manufacturers see standards as the ultimate goal. We see them as the absolute lower limit. Our internal tolerances are many times stricter than what DVGW, ISO, or SKZ require. When a K Aqua pipe leaves our factory, it has been analyzed at the molecular level, tortured with extreme pressures, and thermally pushed to the absolute limit."
  },
  "bento": {
    "eyebrow": "The Pillars of Safety",
    "title": "The DNA of a perfect pipe system.",
    "lead": "When international general contractors plan multi-billion dollar projects, they don't rely on marketing promises. They demand hard, physically measurable facts.",
    "items": [
      {
        "title": "Extreme Pressure Resistance",
        "desc": "Tested for continuous loads up to PN20/PN25. Our burst pressure tests prove reserves that lie far beyond the standards. Burst pipes are a thing of the past."
      },
      {
        "title": "Thermal Sovereignty",
        "desc": "Permanently resistant from -20°C to +95°C. No material fatigue, no structural weakening, even with extreme thermal shocks."
      },
      {
        "title": "Absolute Hygiene",
        "desc": "No corrosion. No incrustation. Food-safe, toxicologically harmless, and resistant to Legionella growth."
      },
      {
        "title": "Fire Protection (B1/B2)",
        "desc": "Classified according to DIN 4102. Flame retardant and minimal smoke development for maximum safety in critical building infrastructures."
      },
      {
        "title": "Life Cycle Guarantee",
        "desc": "A defined service life of 50 years according to the strictest ISO standard. Built in architectural reality, however, to outlast entire generations."
      }
    ]
  },
  "certifications": {
    "eyebrow": "The Authorities",
    "title": "The toughest examiners in the world.",
    "lead": "Only those who pass the most critical external audits may bear the 'German Engineering' label. Here are the institutions that validate our quality.",
    "items": [
      {
        "title": "DVGW, The Highest Authority",
        "p1": "The German Technical and Scientific Association for Gas and Water (DVGW) sets the world's strictest standard for drinking water hygiene and material resistance.",
        "p2": "Our DVGW certification guarantees that K Aqua pipe systems release no toxic substances and promote no microbiological growth under extreme conditions. Every batch undergoes hydrostatic long-term tests (creep rupture test) at 95°C."
      },
      {
        "title": "SKZ, Independent Monitoring",
        "p1": "The South German Plastics Center (SKZ) acts as our incorruptible auditor. External third-party monitoring secures what our internal laboratories already mandate.",
        "p2": "Tested are impact strength, tensile strength, and thermal behavior via DSC analysis (Dynamic Scanning Calorimetry). The SKZ mark is the proof of mechanical perfection, well beyond DIN EN ISO 15874."
      },
      {
        "title": "KTW-BWGL, Absolute Purity",
        "p1": "The evaluation basis for plastics and other organic materials in contact with drinking water (German Environment Agency).",
        "p2": "We exclusively use highly pure polypropylene (PP-R / PPRCT) without harmful additives or heavy metals. The result? Spring water quality straight from the tap. No odor, no taste impairment."
      },
      {
        "title": "ISO 9001 & 14001, Systematic Excellence",
        "p1": "Quality is not a coincidence, but an absolutely reproducible process. Our ISO 9001 certification proves a flawless quality management from raw material acceptance to global goods delivery.",
        "p2": "With ISO 14001 we prove that industrial peak performance and ecological responsibility go hand in hand. Minimized energy consumption, efficient resource utilization, and the 100% recyclability of our PP products."
      }
    ]
  },
  "lab": {
    "eyebrow": "Inside the Lab",
    "title1": "The Anatomy",
    "title2": "of Perfection.",
    "desc": "Before a K Aqua system leaves the factory, it must pass through our in-house test center. A highly equipped facility where we expose materials to conditions they will never experience in reality.",
    "items": [
      {
        "title": "MFR (Melt Flow Rate)",
        "desc": "Control of the melt flow rate to ensure exact viscosity during extrusion and subsequent welding on site."
      },
      {
        "title": "OIT (Oxidation Induction Time)",
        "desc": "Thermal analysis to determine aging resistance. The proof that our stabilizers protect the plastic from degradation for decades."
      },
      {
        "title": "Creep Rupture Test",
        "desc": "Pipe samples are stored in special water baths at 95°C under extreme pressure, for thousands of hours. Without a crack. Without a break."
      }
    ]
  },
  "timeline": {
    "title": "Decades of Innovation.",
    "desc": "Our quality standards were not created overnight. They are the result of decades of engineering art and continuous process optimization.",
    "items": [
      {
        "year": "1990",
        "title": "The Birth of the Standard",
        "text": "As pioneers of plastic pipe extrusion, we implemented internal test procedures early on that went far beyond the industrial requirements of the time. The foundation for an uncompromising quality culture."
      },
      {
        "year": "1995",
        "title": "ISO 9001 Integration",
        "text": "The complete examination of our quality management systems according to ISO 9001. Every move, every raw material batch, every machine setting is now systematically documented and made completely traceable."
      },
      {
        "year": "2005",
        "title": "DVGW & SKZ Certification",
        "text": "Admission into the exclusive circle of DVGW and SKZ certified manufacturers. The official seal for absolute hygiene, extreme pressure resistance, and unsurpassed longevity under the toughest conditions in drinking water applications."
      },
      {
        "year": "2015",
        "title": "Global Standards (WRAS, KTW)",
        "text": "Expansion of certifications for international markets. Fulfillment of the strict KTW guideline (UBA) and the British WRAS specifications. K Aqua becomes the global standard for international megaprojects."
      },
      {
        "year": "2024",
        "title": "Next-Gen Quality Analytics",
        "text": "Introduction of highly automated OIT (Oxidation Induction Time) and MFR (Melt Flow Rate) tests in our own precision laboratory. AI-supported error analysis during extrusion for a 100% zero defect rate."
      }
    ]
  },
  "cta": {
    "title": "Quality you can blindly trust.",
    "desc": "Download our official certificates or speak directly with our Engineering Team about the specifications of your next megaproject.",
    "button1": "Download Certificates",
    "button2": "Contact Technical Support"
  }
},
"glossar": {
  "meta": {
    "title": "Technical Glossary | K Aqua",
    "desc": "K Aqua Glossary: Explore essential terminology, technical definitions, and industry standards for German-engineered PP-R piping systems."
  },
  "hero": {
    "eyebrow": "Technical Glossary",
    "title1": "Terminology of",
    "title2": "Absolute Safety.",
    "desc": "Welcome to the lexical core of pipeline engineering. Here we decode the principles of German Engineering. No marketing. Only physical facts, material science, and industrial authority.",
    "cta1": "Contact Engineering",
    "cta2": "Explore Glossary"
  },
  "manifesto": {
    "eyebrow": "The Doctrine",
    "title": "The Architecture of Infallibility.",
    "lead": "A piping system is the cardiovascular system of any megaproject. A failure means an infrastructural heart attack. That is why we do not speak of pipes, but of vital industrial arteries. Every term in this glossary represents a pillar of our zero-defect philosophy."
  },
  "scroll": {
    "eyebrow": "Kinematics & Material Science",
    "title": "The K Aqua Process.",
    "lead": "From the molecular granulate level to the final pressure test. Understand the physical principles that make our systems indestructible.",
    "items": [
      {
        "title": "High-Pressure Extrusion Dynamics",
        "desc": "Thermoplastic deformation in our plants is subject to precise temperature control accurate to 0.1 °C. This crystalline perfection guarantees a flawless, homogeneous molecular structure that absolutely excludes microscopic cracking (stress cracking) even under extreme pressure and temperature fluctuations. When the material leaves our extruder, it is no longer a simple plastic; it is an industrial monolith."
      },
      {
        "title": "Hydrostatic Stress Tests",
        "desc": "In our testing laboratories, every pipe is subjected to a hydrostatic simulation that exceeds real conditions many times over. We apply internal pressures that are beyond any normative requirement (up to 100 bar, depending on the SDR class). This ensures the integrity of the welds and the molecular elasticity of the PP-R material over a projected lifespan of more than 50 years in critical infrastructures."
      },
      {
        "title": "Polyfusion Welding Technology",
        "desc": "Connections are the weak point in conventional systems. K Aqua eliminates this risk through polyfusion. At the molecular level, pipe and fitting fuse into an inseparable, continuous unit. There are no threads to corrode, no seals that can fail. The result is a piping system that behaves as if it were cast from a single piece."
      },
      {
        "title": "Cavitation Resistance & Fluid Mechanics",
        "desc": "Thanks to an ultra-smooth inner wall (roughness < 0.007 mm), K Aqua pipes minimize flow resistance to almost zero. This prevents the formation of biofilms and eliminates micro-cavitational effects at high flow velocities. Pressure losses in the system are drastically reduced, maximizing the energy efficiency of connected pumping systems on an industrial scale."
      }
    ]
  },
  "bento": {
    "eyebrow": "Nomenclature",
    "title": "Technical Parameters.",
    "lead": "The most important vocabulary of industrial pipeline technology, distilled to its essence.",
    "items": [
      {
        "title": "PP-R (Polypropylene Random Copolymer)",
        "desc": "The molecular basis. A highly crystalline thermoplastic polymer that offers exceptional resistance to high temperatures and pressures. It is the DNA of our longevity."
      },
      {
        "title": "Linear Thermal Expansion",
        "desc": "The change in length of the material during temperature changes. Our fiber-reinforced pipes reduce this value to an absolute minimum (α = 0.035 mm/mK), which enormously increases structural stability in shafts."
      },
      {
        "title": "Creep Rupture Strength",
        "desc": "The ability of the system to withstand constant internal pressure at specific temperatures over decades without deforming or bursting. K Aqua pipes are calibrated for 50+ years."
      },
      {
        "title": "Pressure Loss Coefficient",
        "desc": "A mathematical value that describes the energy loss of the flow due to friction on the inner pipe wall. Thanks to nano-smooth surfaces, this value is marginalized in K Aqua systems."
      },
      {
        "title": "SDR (Standard Dimension Ratio)",
        "desc": "The ratio between the outer diameter (d) and the wall thickness (s). An SDR 6 pipe withstands massively higher pressures than an SDR 11 pipe. The correct choice is crucial for system design.",
        "label": "50+ YRS"
      }
    ]
  },
  "timeline": {
    "title": "Regulatory Rigor.",
    "desc": "Standards are not rules for us, but the starting point of our engineering art. A chronology of the certifications and standards that our systems not only fulfill, but dominate.",
    "items": [
      {
        "year": "DIN 8077/8078",
        "title": "Normative Basis",
        "text": "The foundation of German piping standards. We consider these standards not as a goal, but as the absolute minimum. Our internal tolerances are up to 30% stricter than required by DIN."
      },
      {
        "year": "ISO 15874",
        "title": "Global Testing",
        "text": "The international seal of quality for plastic piping systems for hot and cold water installations. Proof of the uncompromising global applicability of our systems."
      },
      {
        "year": "SDR 6 - SDR 11",
        "title": "Standard Dimension Ratios",
        "text": "A precise ratio of outer diameter to wall thickness. Our engineers calibrate every batch to guarantee maximum pressure resistance with optimal flow rate."
      },
      {
        "year": "SKZ & DVGW",
        "title": "Hygiene & Material Testing",
        "text": "Certificates attesting to absolute food and drinking water safety. No heavy metals, no leaching. Pure, uncontaminated fluid dynamics for the highest hygienic requirements."
      }
    ]
  },
  "conclusion": {
    "title": "Decomposition Resistance in Extreme Cases.",
    "p1": "In industrial applications, it is not normal operation that determines the quality of a piping system, but stability at the limits. Chemical corrosion, cavitation from water hammer, and thermal shocks are the natural enemies of conventional installations.",
    "p2": "The <span class=\"font-semibold\">K Aqua Matrix</span> isolates the fluid medium from the environment with an inert barrier layer. There is no ion exchange. Metallic systems degrade from the moment water flows through them. They sacrifice themselves to function. Our PP-R system remains flawless inside even after decades.",
    "p3": "The concept of <span class=\"font-semibold\">Environmental Stress Cracking Resistance (ESCR)</span> is of central importance in polymer chemistry. We modify the molecular weight of our copolymer so that it cushions load peaks instead of breaking under them. The result is a system that absorbs shocks, vibrations, and structural settlements.",
    "p4": "Anyone who has understood the terminology of pipeline technology also understands why compromises here can mean ruin. German Engineering is not an empty promise, but the sum of precise, physical parameters that we manifest in every single centimeter of our production."
  },
  "cta": {
    "title1": "The theory ends.",
    "title2": "The practice begins.",
    "desc": "Confront our engineers with your toughest technical requirements. We deliver the system architecture.",
    "button": "Start Engineering Briefing"
  }
},
